python3 -c "
from pathlib import Path
text = Path('.env').read_text()
keys = ('BREVO_API_KEY','BREVO_FROM_EMAIL','BREVO_FROM_NAME','PANEL_ADMIN_EMAILS')
for line in text.splitlines():
    s=line.strip()
    if not s or s.startswith('#') or '=' not in s:
        continue
    k,v=s.split('=',1)
    if k in keys:
        v=v.strip().strip('\"').strip(\"'\")
        if k=='BREVO_API_KEY':
            print(f'{k}: set={bool(v)} len={len(v)} prefix={v[:6]!r}...' if v else f'{k}: empty')
        else:
            print(f'{k}={v}')
"
